// Package prompt is the single source of truth for the prompts neokapi sends to
// an LLM.
//
// A prompt is an input to a build: it must be deterministic (the same inputs
// render the same bytes), inspectable (see kapi's --explain), and versioned (a
// changed prompt must not serve output generated by an older one from cache).
// Prompts therefore live here rather than being inlined at each call site, so
// the translate tool's streaming, inline-code and batch paths and the provider
// layer all render the same bytes instead of drifting apart.
//
// Prompts are provider-neutral. They declare roles semantically as Turns; the
// aiprovider layer is responsible for transporting a Turn the way each vendor's
// API expects (Anthropic lifts system into a top-level parameter, Gemini folds
// it into the first user turn, OpenAI carries it as an ordinary message). No
// prompt in this package branches on the provider.
package prompt

import (
	"github.com/neokapi/neokapi/core/locale"
	"github.com/neokapi/neokapi/core/model"
)

// Version is the declared revision of this prompt catalog. It is a label for
// humans — shown by --explain, published in the prompt reference — so a prompt
// can be cited ("translate.single v2") in a bug report or a changelog.
//
// It is deliberately NOT the cache key. Cache invalidation keys off
// Translate.Fingerprint, hashed from the text a prompt actually renders, because
// a version constant is a step someone forgets: reword a prompt, forget the bump,
// and cached translations produced by a prompt that no longer exists get served
// as current. (That happened during development of this package.) Bump Version
// when the change is worth announcing; correctness does not depend on it.
const Version = "v4"

// LanguageName renders a locale for a model to read: the English language name
// with the tag beside it, "Norwegian Bokmål (nb)".
//
// A bare BCP-47 tag is an identifier, and a model has to resolve it before it
// can act on it. A large one usually does; a small one is not reliable. Asked to
// translate "Order Confirmed!" from "en" to "nb", gemma4:e2b returns "Commande
// confirmée !" every time at the sampling temperature kapi uses for local
// models — French, confidently, for a Norwegian target. Told "Norwegian Bokmål
// (nb)" it returns "Ordre bekreftet!". The tag stays because it disambiguates a
// name that does not travel alone (Norwegian has two written standards, and
// zh-Hans is not zh-Hant).
//
// An unnamed tag renders as itself rather than doubled: our pseudo locale qps
// has no CLDR name, and "qps (qps)" tells a reader nothing twice.
func LanguageName(id model.LocaleID) string {
	name := locale.DisplayName(id)
	if name == "" || name == string(id) {
		return string(id)
	}
	return name + " (" + string(id) + ")"
}

// Role names a Turn's speaker. These mirror aiprovider's role constants; this
// package deliberately does not import aiprovider, so that aiprovider can
// import it.
const (
	RoleSystem = "system"
	RoleUser   = "user"
)

// Turn is one message of a rendered prompt. Text is what the model receives;
// Sections is the same content, still attributed to what produced each piece,
// so --explain and the reference docs can show a prompt's provenance rather than
// an opaque wall of English.
type Turn struct {
	Role     string
	Text     string
	Sections []Section
}

// System builds a system turn from its sections.
func System(sections ...Section) Turn {
	return Turn{Role: RoleSystem, Text: renderSections(sections), Sections: sections}
}

// User builds a user turn from its sections.
func User(sections ...Section) Turn {
	return Turn{Role: RoleUser, Text: renderSections(sections), Sections: sections}
}
